#define light 2.*vec3(-1,.8,-1)
vec2 map (vec3 p) {
    float d = 1e4;
    float a = 0.;
    p.xy *= ei(.5*iTime*sqrt(iTime));
    p.z += 1.7;
    vec3 p0 = p;
    for (float i = -1.; i <= 1.; i++) {
        p = p0;
        float K = 10.;
        p.z -= i/K;
        float z = round(p.z*K)/K;

            p.z -= clamp(z,-10.,14.5);
            a = atan(p.y,p.x);
            float N = max(12.+10.*z*4.,1.);
            float n = round(a/pi/2.*N)/N;
            if (z>0.) {
                p.z -= (n+4.*z*K*sin(1.*2.*pi*n+10.+10.*z))/K/N;
                p.z -= (n+1.*z*K*sin(2.*2.*pi*n+10.+10.*z))/K/N;
            }

            p.xy *= ei(n*2.*pi);
        p.z += i/K;
        d = min(d,length(p-vec3(.1+.5*z,0,0))-.035);
    }
    return vec2(d,0.);
}
vec3 normal (vec3 p) {
    vec2 e = vec2(1e-4,0);
    float m = map(p).x;
    return normalize(vec3(
        map(p+e.xyy).x-m,
        map(p+e.yxy).x-m,
        map(p+e.yyx).x-m
    ));

}
Main {
    vec4 H = hash(vec4(iFrame,iTime,U));
    Q = vec4(0);
