    vec3 p = vec3(.5*uu,-3);
    vec3 d = vec3(normalize(vec3(uu,6)));
    p.zy *= ei(-.6);
    d.zy *= ei(-.6);

    vec4 q = max(sin(-2.+6.*H.w+vec4(1,2,3,4)),0.)*150.;
    for (float i = 0.; i < 100.; i++) {
        float m = .5*map(p).x;
        p += max(m,1e-5)*d;
        if (m < 3e-5) {
            vec3 no = normal(p);
            Q.xyz += -.5*no.zzz*exp(-Q.xyz);
            d = reflect(d,no);
            p += .001*d;
        }
        if( p.x>1000.0 ) break; 
    }
    Q *= .5*vec4(4,3,2,1);
}

